            end = r - 1
            if end - start < 2 or grid[start][c] != grid[end][c]:
                continue
            cap = grid[start][c]
            interior = [grid[k][c] for k in range(start + 1, end)]
            if interior and interior[0] != cap and all(v == interior[0] for v in interior):
                bars.setdefault(cap, []).append((len(interior), c, start, end))

    # Select the bar at the marker's rank, ordered longest first.
    for color, rank in ranks.items():
        candidates = sorted(bars.get(color, []), key=lambda item: (-item[0], item[1]))
